'use strict';
const assert = require('node:assert/strict');
const { createParser, parse } = require('./src/csv');

const err = (fn, type, re) => assert.throws(fn, e => e instanceof type && (!re || re.test(e.message)));
assert.deepEqual(parse(''), []);
assert.deepEqual(parse('\uFEFF'), []);
assert.deepEqual(parse('\n'), [['']]);
assert.deepEqual(parse('\n\n'), [[''], ['']]);
assert.deepEqual(parse('a\r\nb\rc\n'), [['a'], ['b'], ['c']]);
assert.deepEqual(parse('a"b,c"'), [['a"b', 'c"']]);
assert.deepEqual(parse('"x\r\ny\rz"'), [['x\r\ny\rz']]);
assert.deepEqual(parse('a,\uFEFFb'), [['a', '\uFEFFb']]);
assert.deepEqual(parse('a;b,c', { delimiter: ';' }), [['a', 'b,c']]);
assert.deepEqual(parse('"",""'), [['', '']]);
err(() => parse('"a" ,b'), SyntaxError, /line 1/);
err(() => parse('"a\r\nb\nc\rd" x'), SyntaxError, /line 4/);
err(() => parse('a\n"b'), SyntaxError, /line 2/);
err(() => parse('a\n"b\n'), SyntaxError, /line 3/);
for (const d of ['', '"', '\r', '\n', ',,', 1, null]) err(() => createParser({ delimiter: d }), RangeError);
createParser({ delimiter: undefined });
const p = createParser();
err(() => p.push(1), TypeError);
assert.deepEqual(p.push('a\r'), [['a']]);
assert.deepEqual(p.push('\nb'), []);
assert.deepEqual(p.end(), [['b']]);
assert.deepEqual(p.end(), []);
err(() => p.push(''), Error);
const q = createParser();
assert.deepEqual(q.push(''), []);
assert.deepEqual(q.push('\uFEFFx'), []);
assert.deepEqual(q.end(), [['x']]);
// CRLF across chunks inside quotes counts once
const r = createParser();
r.push('"a\r'); r.push('\nb"');
err(() => r.push('!'), SyntaxError, /line 2/);
assert.deepEqual(parse('h,h,h_2\n1\n', { header: true }), [{ h: '1', h_2: '', h_2_2: '' }]);

// every 2- and 3-way split equals whole parse (records and errors)
const inputs = ['\uFEFFa,"b""c"\r\n"d\r\ne",f\r\n\r\n', 'x\r\r\n"q""""",\n"', '"a"b\n', '"a\r\n\r\nb" z', 'a,b\rc'];
const run = parts => {
  const s = createParser();
  try {
    const out = [];
    for (const part of parts) out.push(...s.push(part));
    out.push(...s.end());
    return out;
  } catch (e) { return `${e.name}:${e.message}`; }
};
for (const t of inputs) {
  const whole = run([t]);
  for (let i = 0; i <= t.length; i++) {
    for (let j = i; j <= t.length; j++) {
      assert.deepEqual(run([t.slice(0, i), '', t.slice(i, j), t.slice(j)]), whole, `${JSON.stringify(t)} ${i} ${j}`);
    }
  }
  console.log(JSON.stringify(t), JSON.stringify(whole));
}
console.log('ok');
